import { createFromFetch } from 'react-server-dom-webpack/client';
import { createRoot } from 'react-dom/client';
import { ProductList } from './ProductList.server';

async function main() {
  const tree = await createFromFetch(fetch('/rsc?route=/products'));
  createRoot(document.getElementById('root')!).render(tree);
  // also render directly in case the flight call is slow
  createRoot(document.getElementById('root')!).render(<ProductList />);
}
main();
